  function 新建(标签, 类名, 文本) {
    const 节点 = document.createElement(标签);
    if (类名) 节点.className = 类名;
    if (文本 !== undefined && 文本 !== null) 节点.textContent = 文本;
    return 节点;
  }

  function 清空(节点) {
    if (节点) 节点.replaceChildren();
  }

  function 读存储(键, 默认值) {
    try {
      return localStorage.getItem(键) || 默认值;
    } catch (错误) {
      return 默认值;
    }
  }

  function 写存储(键, 值) {
    try {
      localStorage.setItem(键, 值);
    } catch (错误) {
      console.warn('设置保存失败', 键, 错误);
    }
  }

  function 切行(内容) {
    return String(内容 || '').split(/\r?\n/).map(行 => 行.trim()).filter(Boolean);
  }

  function 是空内容(内容) {
    const 文本 = String(内容 || '').trim();
    return !文本 || 空值正则.test(文本);
  }

  function 找分隔位置(行) {
    const 候选 = [行.indexOf(':'), 行.indexOf('：'), 行.indexOf('=')].filter(位置 => 位置 >= 0);
    if (!候选.length) return -1;
    return Math.min(...候选);
  }

  function 按行键值(内容) {
    return 切行(内容).map(行 => {
      const 位置 = 找分隔位置(行);
      if (位置 < 0 || 位置 > 22) return { 键: '', 值: 行 };
      return { 键: 行.slice(0, 位置).trim(), 值: 行.slice(位置 + 1).trim() };
    });
  }

  function 去标签(内容, 标签们) {
    let 文本 = String(内容 || '');
    for (const 标签 of 标签们) {
      文本 = 文本.replace(new RegExp(`<${转义正则(标签)}[^>]*>[\\s\\S]*?<\\/${转义正则(标签)}>`, 'gi'), '');
    }
    return 文本.trim();
  }

  function 取摘要(内容) {
    const 第一行 = 切行(内容)[0] || '';
    const 位置 = 找分隔位置(第一行);
    const 文本 = 位置 >= 0 && 位置 <= 18 ? 第一行.slice(位置 + 1).trim() : 第一行;
    return 文本.length > 42 ? `${文本.slice(0, 42)}...` : 文本;
  }

  function 取头像字(名称) {
    return Array.from(String(名称 || '？').trim())[0] || '？';
  }

  function 生成文本块(内容) {
    return 新建('div', '斗罗文本块', 内容);
  }

  function 生成键值表(内容) {
    const 表 = 新建('div', '斗罗键值');
    for (const 项 of 按行键值(内容)) {
      if (!项.键) {
        const 值 = 新建('div', '斗罗值', 项.值);
        值.style.gridColumn = '1 / -1';
        表.appendChild(值);
        continue;
      }
      表.appendChild(新建('div', '斗罗键', 项.键));
      表.appendChild(新建('div', '斗罗值', 项.值));
    }
    return 表;
  }

  function 生成字段组(内容, 高亮台词) {
    const 组 = 新建('div', '斗罗字段组');
    const 项们 = 按行键值(内容);
    if (!项们.length) {
      组.appendChild(生成文本块(内容));
      return 组;
    }
    for (const 项 of 项们) {
      if (!项.键) {
        组.appendChild(新建('div', '斗罗字段值', 项.值));
        continue;
      }
      const 行 = 新建('div', '斗罗字段行');
      行.appendChild(新建('div', '斗罗字段名', 项.键));
      const 值 = 新建('div', '斗罗字段值', 项.值);
      if (高亮台词 && /「[^」]+」|"[^"]+"/.test(项.值)) 值.classList.add('斗罗台词');
      行.appendChild(值);
      组.appendChild(行);
    }
    return 组;
  }

  function 分块步骤(内容) {
    const 分块 = [];
    const 正则 = /(step\s*\d+[^：:\n]*(?:[：:]|）)?|【[^】]+】)/gi;
    let 上次 = 0;
    let 当前标题 = '';
    let 匹配;
    while ((匹配 = 正则.exec(内容))) {
      const 前文 = 内容.slice(上次, 匹配.index).trim();
      if (前文 || 当前标题) 分块.push({ 标题: 当前标题 || '内容', 内容: 前文 });
      当前标题 = 匹配[0].trim();
      上次 = 正则.lastIndex;
    }
    const 收尾 = 内容.slice(上次).trim();
    if (收尾 || 当前标题) 分块.push({ 标题: 当前标题 || '内容', 内容: 收尾 });
    return 分块.filter(项 => 项.内容 || 项.标题);
  }

  function 生成步骤块(内容) {
    const 块 = 新建('div', '斗罗步骤块');
    const 步骤 = 分块步骤(内容);
    if (!步骤.length) {
      块.appendChild(生成文本块(内容));
      return 块;
    }
    for (const 项 of 步骤) {
      const 节点 = 新建('div', '斗罗步骤');
      节点.appendChild(新建('div', '斗罗步骤标题', 项.标题));
      if (项.内容) 节点.appendChild(生成文本块(项.内容));
      块.appendChild(节点);
    }
    return 块;
  }

  function 生成条目列(内容) {
    const 列 = 新建('div', '斗罗条目列');
    切行(内容).forEach((行, 序号) => {
      const 条 = 新建('div', '斗罗条目 斗罗编号条目');
      条.appendChild(新建('span', '斗罗编号', String(序号 + 1)));
      条.appendChild(新建('span', '', 行));
      列.appendChild(条);
    });
    return 列;
  }

  function 生成折叠卡(标题, 内容, 移动折叠, 渲染器) {
    const 卡 = 新建('section', '斗罗折叠卡');
    const 移动端 = typeof window.matchMedia === 'function' && window.matchMedia('(max-width: 760px)').matches;
    卡.dataset.collapsed = 移动折叠 && 移动端 ? 'true' : 'false';
    const 头 = 新建('button', '斗罗折叠头');
    头.type = 'button';
    头.appendChild(新建('span', '', 标题));
    头.appendChild(新建('span', '斗罗小标记', '展开'));
    const 体 = 新建('div', '斗罗折叠体');
    体.appendChild(渲染器 ? 渲染器(内容) : 生成文本块(内容));
    头.addEventListener('click', () => {
      卡.dataset.collapsed = 卡.dataset.collapsed === 'true' ? 'false' : 'true';
    });
    卡.appendChild(头);
    卡.appendChild(体);
    return 卡;
  }

  function 生成行动卡(项) {
    const 名称 = 取属性(项.属性, 'name') || '角色';
    const 卡 = 新建('article', '斗罗正文卡 斗罗行动卡');
    卡.appendChild(新建('div', '斗罗角色名', 名称));
    卡.appendChild(生成字段组(项.内容, true));
    return 卡;
  }

  function 生成内心卡(项) {
    const 名称 = 项.名称 || 取属性(项.属性, 'name') || 'NPC';
    const 卡 = 新建('article', '斗罗内心卡');
    卡.appendChild(新建('div', '斗罗角色名', 名称));
    卡.appendChild(生成字段组(项.内容, false));
    return 卡;
  }

  function 生成旁白(内容) {
    return 新建('div', '斗罗旁白', 内容);
  }

  function 解析旁白(舞台内容) {
    const 旁白 = [];
    for (const 项 of 取全部(舞台内容, 'interplay')) {
      if (!是空内容(项.内容)) 旁白.push(项.内容);
    }
    const 残余 = 去标签(舞台内容, ['act', 'interplay']);
    for (const 行 of 切行(残余)) {
      const 匹配 = /^interplay\s*[：:=]\s*(.+)$/i.exec(行);
      const 内容 = 匹配 ? 匹配[1].trim() : 行;
      if (!/[<>]/.test(内容) && !是空内容(内容)) 旁白.push(内容);
    }
    return 旁白;
  }

  function 渲染场景(面板, 文本) {
    const 容器 = 面板.querySelector('[data-role="场景徽章"]');
    清空(容器);
    const 场景 = 取单个(文本, 'scene');
    if (!容器 || 是空内容(场景)) return 0;
    const 片段们 = 场景.split(/\s*[|｜,，]\s*/).map(项 => 项.trim()).filter(Boolean);
    for (const 片段 of 片段们) 容器.appendChild(新建('span', '斗罗徽章', 片段));
    return 片段们.length;
  }

  function 渲染档案(面板, 文本) {
    const 区 = 面板.querySelector('[data-role="档案区"]');
    const 列 = 面板.querySelector('[data-role="档案列"]');
    清空(列);
    const 档案 = 取全部(文本, 'npc_profile');
    if (!区 || !列 || !档案.length) {
      if (区) 区.classList.add('斗罗隐藏');
      return 0;
    }
    区.classList.remove('斗罗隐藏');
    for (const 项 of 档案) {
      const 名称 = 取属性(项.属性, 'name') || 'NPC';
      const 卡 = 新建('article', '斗罗档案卡');
      卡.tabIndex = 0;
      卡.setAttribute('role', 'button');
      卡.setAttribute('aria-expanded', 'false');
      卡.dataset.open = 'false';
      const 头 = 新建('div', '斗罗档案头');
      头.appendChild(新建('div', '斗罗头像', 取头像字(名称)));
      头.appendChild(新建('div', '斗罗档案名', 名称));
      const 详情 = 新建('div', '斗罗档案详情');
      const 摘要 = 取摘要(项.内容);
      if (摘要) 详情.appendChild(新建('div', '斗罗档案摘要', 摘要));
      详情.appendChild(生成键值表(项.内容));
      卡.appendChild(头);
      卡.appendChild(详情);
      列.appendChild(卡);
    }
    return 档案.length;
  }

  function 建内心池(文本) {
    return 取全部(文本, 'npc_inner').map((项, 序号) => ({
      序号,
      属性: 项.属性,
      内容: 项.内容,
      名称: 取属性(项.属性, 'name') || 'NPC',
      已用: false
    }));
  }

  function 取匹配内心(内心池, 名称) {
    const 命中 = 内心池.find(项 => !项.已用 && 项.名称 === 名称);
    if (命中) 命中.已用 = true;
    return 命中;
  }

  function 渲染正文(面板, 文本) {
    const 容器 = 面板.querySelector('[data-role="正文列"]');
    清空(容器);
    if (!容器) return 0;
    const 内心池 = 建内心池(文本);
    const 舞台们 = 取全部(文本, 'stage');
    const 来源们 = 舞台们.length ? 舞台们.map(项 => 项.内容) : [文本];
    let 数量 = 0;

    for (const 舞台 of 来源们) {
      for (const 行动 of 取全部(舞台, 'act')) {
        const 名称 = 取属性(行动.属性, 'name') || '角色';
        容器.appendChild(生成行动卡(行动));
        数量 += 1;
        const 内心 = 取匹配内心(内心池, 名称);
        if (内心) {
          容器.appendChild(生成内心卡(内心));
          数量 += 1;
        }
      }
      for (const 旁白 of 解析旁白(舞台)) {
        容器.appendChild(生成旁白(旁白));
        数量 += 1;
      }
    }

    for (const 内心 of 内心池.filter(项 => !项.已用)) {
      容器.appendChild(生成内心卡(内心));
      数量 += 1;
    }

    if (!数量) {
      const 舞台正文 = 舞台们.map(项 => 去标签(项.内容, ['npc_inner'])).join('\n').trim();
      if (!是空内容(舞台正文)) {
        const 卡 = 新建('article', '斗罗正文卡');
        卡.appendChild(生成文本块(舞台正文));
        容器.appendChild(卡);
        数量 += 1;
      }
    }
    return 数量;
  }

  function 生成轨迹列(内容) {
    const 列 = 新建('div', '斗罗瀑布');
    for (const 项 of 内容) {
      const 卡 = 新建('article', '斗罗条目');
      卡.appendChild(新建('div', '斗罗角色名', 项.名称));
      卡.appendChild(生成字段组(项.内容, false));
      列.appendChild(卡);
    }
    return 列;
  }

  function 渲染幕后动向(容器, 文本) {
    let 数量 = 0;
    const 角色轨迹 = 取全部(文本, 'npc_track').map(项 => ({ 名称: 取属性(项.属性, 'name') || 'NPC', 内容: 项.内容 }));
    const 跳跃轨迹 = 取全部(文本, 'npc_jump').map(项 => {
      const 名称 = 取属性(项.属性, 'name') || 'NPC';
      const 时间 = 取属性(项.属性, '跃过时间');
      return { 名称: 时间 ? `${名称} ${时间}` : 名称, 内容: 项.内容 };
    });
    if (角色轨迹.length) {
      容器.appendChild(生成折叠卡('npc_track', 角色轨迹, false, 生成轨迹列));
      数量 += 1;
    }
    if (跳跃轨迹.length) {
      容器.appendChild(生成折叠卡('npc_jump', 跳跃轨迹, false, 生成轨迹列));
      数量 += 1;
    }
    const 幕后 = 去标签(取单个(文本, 'dmtrack'), ['scene', 'npc_track', 'npc_jump']);
    if (!是空内容(幕后)) {
      容器.appendChild(生成折叠卡('dmtrack', 幕后, true, 生成步骤块));
      数量 += 1;
    }
    return 数量;
  }

  function 渲染世界账本(容器, 文本) {
    let 数量 = 0;
    const 账本 = 取单个(文本, 'dm_box');
    const 设定 = 取单个(文本, 'dm_set');
    if (!是空内容(账本)) {
      容器.appendChild(生成折叠卡('dm_box', 账本, true, 生成字段组));
      数量 += 1;
    }
    if (!是空内容(设定)) {
      容器.appendChild(生成折叠卡('dm_set', 设定, true, 生成步骤块));
      数量 += 1;
    }
    return 数量;
  }

  function 渲染裁定推演(容器, 文本) {
    const 瀑布 = 新建('div', '斗罗瀑布');
    const 路由 = 取单个(文本, '模块路由');
    const 配置 = [
      ['recall', 取单个(文本, 'recall'), 生成条目列],
      ['timeline_recall', 取单个(文本, 'timeline_recall'), 生成条目列],
      ['偏差账本召回', 取单个(文本, '偏差账本召回'), 生成条目列],
      ['剧情审查', 取单个(文本, '剧情审查'), 生成步骤块],
      ['dm_plan', 取单个(文本, 'dm_plan'), 生成步骤块]
    ];
    let 数量 = 0;
    if (!是空内容(路由)) {
      const 卡 = 新建('section', '斗罗折叠卡 斗罗路由详情');
      卡.dataset.hit = 路由命中(路由) ? 'true' : 'false';
      卡.appendChild(新建('div', '斗罗卡标题', '模块路由'));
      卡.appendChild(生成字段组(路由, false));
      瀑布.appendChild(卡);
      数量 += 1;
    }
    for (const [标题, 内容, 渲染器] of 配置) {
      if (是空内容(内容)) continue;
      瀑布.appendChild(生成折叠卡(标题, 内容, true, 渲染器));
      数量 += 1;
    }
    if (数量) 容器.appendChild(瀑布);
    return 数量;
  }

  function 路由命中(内容) {
    if (是空内容(内容)) return false;
    return !/未命中/.test(内容);
  }

  function 设置空标签(面板, 标签, 数量) {
    const 按钮 = 面板.querySelector(`[data-tab="${标签}"]`);
    if (!按钮) return;
    按钮.dataset.empty = 数量 ? 'false' : 'true';
  }

  function 渲染图层(面板, 文本) {
    const 面板们 = {
      dmtrack: 面板.querySelector('[data-tab-panel="dmtrack"]'),
      dm_box: 面板.querySelector('[data-tab-panel="dm_box"]'),
      review: 面板.querySelector('[data-tab-panel="review"]')
    };
    Object.values(面板们).forEach(清空);
    const 幕后数 = 渲染幕后动向(面板们.dmtrack, 文本);
    const 账本数 = 渲染世界账本(面板们.dm_box, 文本);
    const 推演数 = 渲染裁定推演(面板们.review, 文本);
    设置空标签(面板, 'dmtrack', 幕后数);
    设置空标签(面板, 'dm_box', 账本数);
    设置空标签(面板, 'review', 推演数);
    return 幕后数 + 账本数 + 推演数;
  }

  function 设置主题(面板, 名称) {
    const 主题 = 主题列表.includes(名称) ? 名称 : 主题列表[0];
    面板.dataset.theme = 主题;
    for (const 按钮 of 面板.querySelectorAll('[data-theme-name]')) {
      按钮.setAttribute('aria-pressed', 按钮.dataset.themeName === 主题 ? 'true' : 'false');
    }
    写存储(主题存储键, 主题);
  }

  function 设置字号(面板, 值) {
    const 字号 = 字号列表.includes(String(值)) ? String(值) : '1';
    面板.style.setProperty('--font-scale', 字号);
    写存储(字号存储键, 字号);
  }

  function 切换字号(面板) {
    const 当前 = getComputedStyle(面板).getPropertyValue('--font-scale').trim() || '1';
    const 序号 = 字号列表.indexOf(当前);
    设置字号(面板, 字号列表[(序号 + 1) % 字号列表.length]);
  }

  function 设置密度(面板, 值) {
    const 密度 = 值 === '紧凑' ? '紧凑' : '标准';
    面板.dataset.density = 密度;
    写存储(密度存储键, 密度);
  }

  function 切换密度(面板) {
    设置密度(面板, 面板.dataset.density === '紧凑' ? '标准' : '紧凑');
  }

  function 切换档案(卡) {
    const 列 = 卡.closest('[data-role="档案列"]');
    const 打开 = 卡.dataset.open === 'true';
    if (列) {
      for (const 同级 of 列.querySelectorAll('.斗罗档案卡')) {
        同级.dataset.open = 'false';
        同级.setAttribute('aria-expanded', 'false');
      }
    }
    卡.dataset.open = 打开 ? 'false' : 'true';
    卡.setAttribute('aria-expanded', 打开 ? 'false' : 'true');
  }

  function 切换标签(面板, 名称) {
    const 当前按钮 = 面板.querySelector(`[data-tab="${名称}"]`);
    const 当前内容 = 面板.querySelector(`[data-tab-panel="${名称}"]`);
    if (!当前按钮 || !当前内容) return;
    for (const 按钮 of 面板.querySelectorAll('[data-tab]')) 按钮.dataset.active = 按钮 === 当前按钮 ? 'true' : 'false';
    for (const 内容 of 面板.querySelectorAll('[data-tab-panel]')) 内容.dataset.active = 内容 === 当前内容 ? 'true' : 'false';
  }

  function 绑定交互(面板) {
    设置主题(面板, 读存储(主题存储键, 主题列表[0]));
    设置字号(面板, 读存储(字号存储键, '1'));
    设置密度(面板, 读存储(密度存储键, '标准'));

    面板.addEventListener('click', 事件 => {
      const 主题按钮 = 事件.target.closest('[data-theme-name]');
      if (主题按钮 && 面板.contains(主题按钮)) {
        设置主题(面板, 主题按钮.dataset.themeName);
        return;
      }

      const 工具按钮 = 事件.target.closest('[data-action]');
      if (工具按钮 && 面板.contains(工具按钮)) {
        if (工具按钮.dataset.action === 'font') 切换字号(面板);
        if (工具按钮.dataset.action === 'density') 切换密度(面板);
        return;
      }

      const 标签按钮 = 事件.target.closest('[data-tab]');
      if (标签按钮 && 面板.contains(标签按钮)) {
        切换标签(面板, 标签按钮.dataset.tab);
        return;
      }

      const 档案卡 = 事件.target.closest('.斗罗档案卡');
      if (档案卡 && 面板.contains(档案卡)) 切换档案(档案卡);
    });

    面板.addEventListener('keydown', 事件 => {
      const 档案卡 = 事件.target.closest('.斗罗档案卡');
      if (!档案卡 || !面板.contains(档案卡)) return;
      if (事件.key !== 'Enter' && 事件.key !== ' ') return;
      事件.preventDefault();
      切换档案(档案卡);
    });
  }

  function 启动(面板) {
    if (面板.getAttribute('data-已启动') === 'true') return;
    面板.setAttribute('data-已启动', 'true');
    const 缓冲区 = 面板.querySelector('.斗罗缓冲区');
    const 文本 = 缓冲区 ? 缓冲区.value : '';
    绑定交互(面板);
    const 场景数 = 渲染场景(面板, 文本);
    const 档案数 = 渲染档案(面板, 文本);
    const 正文数 = 渲染正文(面板, 文本);
    const 数据数 = 渲染图层(面板, 文本);
    切换标签(面板, 'story');
    const 统计 = 面板.querySelector('[data-role="统计"]');
    if (统计) 统计.textContent = `场景 ${场景数} / 档案 ${档案数} / 正文 ${正文数} / 数据 ${数据数}`;
    const 空态 = 面板.querySelector('[data-role="空态"]');
    if (空态 && !场景数 && !档案数 && !正文数 && !数据数) 空态.classList.remove('斗罗隐藏');
  }

  for (const 面板 of document.querySelectorAll('.斗罗面板')) {
    启动(面板);
  }
})();

